<?php

use App\Models\{Company,Customer,InventoryBalance,Permission,Product,ProductVariant,Role,RoleAssignment,SalesOrder,Tenant,TenantMembership,UnitOfMeasure,User,Warehouse,WarehouseLocation};

function salesOrderPhase5Fixture(): array
{
    $user=User::factory()->create();$tenant=Tenant::factory()->create();TenantMembership::create(['tenant_id'=>$tenant->id,'user_id'=>$user->id,'status'=>'active']);$permissions=collect(['sales.manage','sales.approve'])->map(fn($n)=>Permission::firstOrCreate(['name'=>$n]));$role=Role::create(['tenant_id'=>$tenant->id,'name'=>'Order operator','slug'=>'order-operator']);$role->permissions()->sync($permissions->pluck('id')->all());RoleAssignment::create(['tenant_id'=>$tenant->id,'role_id'=>$role->id,'user_id'=>$user->id]);$company=Company::create(['tenant_id'=>$tenant->id,'name'=>'Order Company','code'=>'SO']);$customer=\App\Models\Customer::create(['tenant_id'=>$tenant->id,'company_id'=>$company->id,'name'=>'Order customer','code'=>'SO-C','customer_type'=>'business']);$unit=UnitOfMeasure::create(['tenant_id'=>$tenant->id,'name'=>'Each','code'=>'SO-EA']);$product=Product::create(['tenant_id'=>$tenant->id,'name'=>'Order product','slug'=>'order-product','status'=>'active']);$variant=ProductVariant::create(['tenant_id'=>$tenant->id,'product_id'=>$product->id,'unit_id'=>$unit->id,'sku'=>'SO-1','internal_barcode'=>'SO-1','price'=>'25','cost'=>'10','is_active'=>true]);$warehouse=Warehouse::create(['tenant_id'=>$tenant->id,'company_id'=>$company->id,'name'=>'Order warehouse','code'=>'SO-W','is_active'=>true]);$location=WarehouseLocation::create(['tenant_id'=>$tenant->id,'warehouse_id'=>$warehouse->id,'name'=>'Available','code'=>'SO-A','is_active'=>true]);InventoryBalance::create(['tenant_id'=>$tenant->id,'variant_id'=>$variant->id,'location_id'=>$location->id,'quantity'=>'10','reserved_quantity'=>'0']);return compact('user','tenant','company','customer','variant','location');
}

it('keeps draft creation and confirmation reservation-only',function():void{$f=salesOrderPhase5Fixture();$h=['X-Tenant-Id'=>$f['tenant']->id];$payload=['company_id'=>$f['company']->id,'customer_id'=>$f['customer']->id,'items'=>[['variant_id'=>$f['variant']->id,'preferred_location_id'=>$f['location']->id,'ordered_quantity'=>'3','unit_price'=>'25']]];$order=$this->actingAs($f['user'])->postJson('/api/v1/sales/orders',$payload,$h)->assertCreated()->json('data');expect(InventoryBalance::first()->reserved_quantity)->toBe('0.000000');$this->actingAs($f['user'])->postJson('/api/v1/sales/orders/'.$order['id'].'/confirm',[],$h)->assertOk();$balance=InventoryBalance::first();expect($balance->quantity)->toBe('10.000000')->and($balance->reserved_quantity)->toBe('3.000000')->and(\App\Models\StockReservation::count())->toBe(1);});

it('does not create a second reservation on repeated confirmation',function():void{$f=salesOrderPhase5Fixture();$h=['X-Tenant-Id'=>$f['tenant']->id];$order=$this->actingAs($f['user'])->postJson('/api/v1/sales/orders',['company_id'=>$f['company']->id,'customer_id'=>$f['customer']->id,'items'=>[['variant_id'=>$f['variant']->id,'preferred_location_id'=>$f['location']->id,'ordered_quantity'=>'3','unit_price'=>'25']]],$h)->json('data');$this->actingAs($f['user'])->postJson('/api/v1/sales/orders/'.$order['id'].'/confirm',[],$h)->assertOk();$this->actingAs($f['user'])->postJson('/api/v1/sales/orders/'.$order['id'].'/confirm',[],$h)->assertOk();expect(InventoryBalance::first()->reserved_quantity)->toBe('3.000000')->and(\App\Models\StockReservation::count())->toBe(1);});
